-- Vote and check-in rows behind the cached counts, so recomputing after a new vote keeps them.
WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
INSERT OR IGNORE INTO users (id, email, display_name, role, karma, verified_posts, email_verified, created_at)
SELECT 'ex_voter' || n, 'ex_voter' || n || '@example.invalid', 'Voter ' || n, 'user', 20, 0, 1, CAST(strftime('%s','now') AS INTEGER)*1000 - 90*86400000 FROM s;

WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
INSERT OR IGNORE INTO votes (user_id, popup_id, kind, value, weight, ip_hash, created_at)
SELECT 'ex_voter' || s.n, p.id, 'existence', 1, p.exist_pos * 1.0 / (p.voter_count - (p.exist_neg > 0)), 'exip' || s.n, CAST(strftime('%s','now') AS INTEGER)*1000
FROM popups p JOIN s ON s.n <= p.voter_count - (p.exist_neg > 0) WHERE p.is_example = 1 AND p.exist_pos > 0;

INSERT OR IGNORE INTO votes (user_id, popup_id, kind, value, weight, ip_hash, created_at)
SELECT 'ex_voter160', id, 'existence', -1, exist_neg, 'exip160', CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups WHERE is_example = 1 AND exist_neg > 0;

WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
INSERT OR IGNORE INTO votes (user_id, popup_id, kind, value, weight, created_at)
SELECT 'ex_voter' || s.n, p.id, 'quality', CASE WHEN s.n <= p.quality_pos - 1 THEN 1 ELSE -1 END, 1, CAST(strftime('%s','now') AS INTEGER)*1000
FROM popups p JOIN s ON s.n <= p.quality_pos - 1 + p.quality_neg WHERE p.is_example = 1;
INSERT OR IGNORE INTO votes (user_id, popup_id, kind, value, weight, created_at)
SELECT created_by, id, 'quality', 1, 1, CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups WHERE is_example = 1 AND quality_pos > 0;

WITH RECURSIVE s(n) AS (SELECT 1 UNION ALL SELECT n + 1 FROM s WHERE n < 160)
INSERT OR IGNORE INTO checkins (user_id, popup_id, distance_m, valid, created_at)
SELECT 'ex_voter' || s.n, p.id, 40, 1, CAST(strftime('%s','now') AS INTEGER)*1000 FROM popups p JOIN s ON s.n <= p.checkin_count WHERE p.is_example = 1;

